for i in range(12):history[f'other-projects/minutes-{i:02}.md']=f'2026-11-{i+1:02} OTHER PROJECT: {"Warehouse routing" if i%2 else "Music practice"}. Discussion, stairs, capacity, encoding and selection are agenda keywords here. These notes do not govern Study spaces. Team {i} requested '+('hide all unknown inventory rows in a staff-only table.' if i%2 else 'show stairs icons on a fictional game board; this is not venue accessibility data.')
for name,body in history.items():p=B/'corpus'/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(body+'\n',encoding='utf-8')
shutil.copytree(R/'experiments/autonomy-readiness/workflow-snapshot',B/'workflow-snapshot')
common='''Authorized local study-space finder repair. Read TASK.md, data.json, app.mjs/index.html and retrieve relevant current feedback from ../../corpus using your available retrieval method. Both methods must verify relevant source documents, preserve dates/authority, and avoid irrelevant project notes. Use ../../workflow-snapshot/docs/workflows/deliver-change.md and relevant skills selectively. Snapshot and inputs read-only. Own only this build directory's app.mjs,index.html,DELIVERY.md,MEMORY.md and local tests/screenshots. You are not alone; preserve others' work. No original repo/prior experiment/other-arm/evaluator reads. No network except assigned loopback, install, external contact, deployment, git writes or subagents. Six minutes from dispatch, at most three correction rounds; no parent coaching. Record retrieved source paths, why applicable/superseded, actions/checks, actual query commands and stop reason. Avoid unnecessary clarification; record consequential unknowns. Runtime contract: assess(place,preferences) returns {state,reasons}, states suitable/unsuitable/needs-confirmation; data.json authoritative; all places article[data-id][data-state]; button[data-select=ID]; one #detail[data-id] and #preference-summary. Contacts from source. No fixture-ID hardcoding. Browser: existing absolute file:///C:/Users/maker/Documents/Projects/visuAI-DLC/visuAI-DLC/experiments/coffee-atlas/node_modules/@playwright/test/index.mjs, chromium executable C:/Users/maker/AppData/Local/ms-playwright/chromium-1234/chrome-win64/chrome.exe. Capture and inspect screenshots using view_image. Existing runtime dependencies only.'''
for arm in ['F','G']:
 d=B/arm/'build';d.mkdir(parents=True)
 for name in ['data.json','app.mjs','index.html']:shutil.copyfile(R/'output/autonomy-readiness/baseline/W'/name,d/name)
 (d/'TASK.md').write_text('Repair the study-space comparison/contact finder for the current user. Relevant requirements and user feedback are scattered in the supplied corpus; recover their meaning and make the app satisfy them. Keep the existing scope and a simple readable phone/desktop interface. All data and history are synthetic. Do not invent facts. No accounts, booking, external services or sending messages.\n',encoding='utf-8')
 extra=('Use ordinary file listing/search/read (rg, etc.). No graph, semantic extraction output or Graphify access.' if arm=='F' else 'Graphify-assisted retrieval: graphify query "TERMS" --graph ../../graphify-out/graph.json --budget 1500. Use actual graph vocabulary (labels in graph JSON) to expand terms before query; record expanded query. Can also use graphify explain/path. Read original cited corpus documents to verify results. Graph source paths are relative to corpus. Fall back to file search if needed, explicitly recording why. Do not treat graph omissions as proof of absence. Query log must be disabled with GRAPHIFY_QUERY_LOG_DISABLE=1; do not update index or save-result.')
 (d/'RUN.md').write_text(common+'\n'+extra+f'\nURL http://127.0.0.1:17832/{arm}/build/\n',encoding='utf-8')
e=(R/'experiments/autonomy-readiness/evaluate.mjs').read_text(encoding='utf-8').replace('autonomy-readiness','graphify-feedback').replace("['P','W']","['F','G']").replace('17831','17832')
(B/'evaluate.mjs').write_text(e,encoding='utf-8')
(O/'input-hashes.json').write_text(json.dumps({str(p.relative_to(R)):hashlib.sha256(p.read_bytes()).hexdigest() for p in B.rglob('*') if p.is_file()},indent=2),encoding='utf-8')
print(f'Prepared {len(history)} corpus documents; identical F/G starters, workflow and evaluator.')
